<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
final class SeatingView
{
    private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
    private static function hidden(string $n,mixed $v):string{return '<input type="hidden" name="'.$n.'" value="'.self::h($v).'">';}
    private static function input(string $label,string $name,string $value='',string $type='text',bool $required=true):string{return '<label>'.self::h($label).'<input name="'.$name.'" type="'.$type.'" value="'.self::h($value).'"'.($required?' required':'').'></label>';}
    private static function select(string $label,string $name,array $choices,string $selected=''):string{$x='<label>'.self::h($label).'<select name="'.$name.'">';foreach($choices as $v=>$text)$x.='<option value="'.self::h($v).'"'.((string)$v===$selected?' selected':'').'>'.self::h($text).'</option>';return $x.'</select></label>';}
    private static function form(array $s,string $csrf,string $op,array $hidden=[]):string{$x='<form method="post" data-seating-form>';foreach(['_csrf'=>$csrf,'action'=>'seating-'.$op,'merchant'=>$s['merchant'],'outlet'=>$s['outlet'],'request'=>bin2hex(random_bytes(16))]+$hidden as $k=>$v)$x.=self::hidden($k,$v);return $x;}
    public static function render(array $s,string $csrf,string $message='',bool $error=false):string{
        $h=static fn($v)=>self::h($v);$zone=$s['settings']['timezone_name'];$when=static fn($t)=>Seating::local((int)$t,$zone);$floors=array_column($s['floors'],'name','floor_id');$tables=[];foreach($s['tables']as $t)$tables[$t['table_id']]=$t['name'].' · '.$t['capacity'].' seats';
        $x='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Floor Manager · KIOS</title><link rel="stylesheet" href="/assets/merchant-setup.css"><link rel="stylesheet" href="/assets/seating.css"><script src="/assets/seating.js" defer></script></head><body><main data-seating data-merchant="'.$h($s['merchant']).'" data-outlet="'.$h($s['outlet']).'"><header><div><p class="eyebrow">Restaurant operations · Private demonstration</p><h1>Floor Manager</h1><p>Tables, arrivals and reservations · '.$h($zone).'</p></div><a class="seating-refresh" href="?seating=1&amp;merchant='.$h($s['merchant']).'&amp;outlet='.$h($s['outlet']).'">Refresh workspace</a></header><p class="notice">Synthetic guests only. Ordering is closed. No sales, payments or print jobs are created here.</p>';
        if($message!=='')$x.='<p class="message'.($error?' error':'').'" role="'.($error?'alert':'status').'">'.$h($message).'</p>';
        $active=array_filter($s['tables'],fn($t)=>(int)$t['active']&&($s['floors'][array_search($t['floor_id'],array_column($s['floors'],'floor_id'))]['active']??false));$seats=array_sum(array_column($active,'capacity'));
        $x.='<nav class="seating-tabs" aria-label="Floor Manager sections"><a href="#floor-workspace">Floor workspace</a><a href="#new-reservation">New reservation</a><a href="#reservations">Reservations</a>'.($s['canConfigure']?'<a href="#configuration">Configuration</a>':'').'<a href="#seating-history">Activity</a></nav><section class="merchant-metrics" aria-label="Outlet seating overview"><article><strong>'.count($active).'</strong><span>Active tables</span></article><article><strong>'.$seats.'</strong><span>Configured seats</span></article><article><strong>'.count(array_filter($s['reservations'],fn($r)=>in_array($r['status'],['REQUESTED','CONFIRMED','SEATED'],true))).'</strong><span>Pending / seated in loaded view</span></article></section><section class="panel" id="floor-workspace"><div class="seating-section-heading"><div><h2>Floor workspace</h2><p>Future bookings do not change a table’s present operational state.</p></div><label>Choose floor<select data-floor-filter><option value="">All floors</option>';
        foreach($s['floors']as $f)$x.='<option value="'.$h($f['floor_id']).'">'.$h($f['name']).(!$f['active']?' · inactive':'').'</option>';
        $x.='</select></label></div><p data-floor-summary role="status"></p><div class="seating-workspace"><div class="seating-grid" aria-label="Select a table">';
        foreach($s['tables']as $t){$label=str_replace('_',' ',strtolower($t['operational_state']));$x.='<button type="button" class="seating-table state-'.strtolower($t['operational_state']).'" data-table-select="'.$h($t['table_id']).'" data-floor="'.$h($t['floor_id']).'" data-capacity="'.$t['capacity'].'" data-active="'.$t['active'].'" aria-controls="table-'.$h($t['table_id']).'" aria-pressed="false"><strong>'.$h($t['name']).'</strong><span>'.$h($floors[$t['floor_id']]).'</span><span>'.$t['capacity'].' seats · '.$h($t['table_type']).'</span><b>'.($t['active']?$h(ucfirst($label)):'Inactive').'</b></button>';}
        if(!$s['tables'])$x.='<p>No tables yet. An owner or outlet manager can add floors and tables under Configuration.</p>';
        $x.='</div><aside class="seating-details" aria-label="Selected table"><p data-table-prompt>Select a table to view its bookings and actions.</p>';
        foreach($s['tables']as $t){$x.='<section id="table-'.$h($t['table_id']).'" data-table-details="'.$h($t['table_id']).'" hidden><h3>'.$h($t['name']).'</h3><p>'.$h($floors[$t['floor_id']]).' · '.$t['capacity'].' seats</p><p><strong>'.$h(str_replace('_',' ',$t['operational_state'])).'</strong>'.($t['operational_until']?' until '.$when($t['operational_until']):'').'</p><p>'.$h($t['notes']).'</p><button type="button" data-reserve-table="'.$h($t['table_id']).'">Reserve this table</button><h4>Pending bookings</h4>';
            $bookings=array_filter($s['reservations'],fn($r)=>$r['table_id']===$t['table_id']&&in_array($r['status'],['REQUESTED','CONFIRMED','SEATED'],true));foreach($bookings as $r)$x.='<p><a href="#reservation-'.$h($r['reservation_id']).'">'.$h($r['guest_name']).' · '.$when($r['start_epoch']).' · '.$h($r['status']).'</a></p>';if(!$bookings)$x.='<p>No pending bookings in the loaded view.</p>';
            $x.='<details><summary>Change present table status</summary><p>Use Complete on a seated reservation to release its table. Manual holds and walk-ins need a duration and reason.</p>'.self::form($s,$csrf,'status',['table'=>$t['table_id'],'version'=>$t['version']]).self::select('Present operational state','state',['AVAILABLE'=>'Available / release','RESERVED'=>'Manual hold','OCCUPIED'=>'Walk-in occupied','OUT_OF_SERVICE'=>'Out of service']).self::input('Expected minutes (hold / walk-in)','minutes','60','number').self::input('Party size (walk-in)','party','1','number').self::input('Reason','reason').'<button>Update table status</button></form></details></section>';
        }
        $x.='</aside></div></section><section class="panel" id="new-reservation"><h2>New reservation</h2><p>A request is tentative until confirmed. Confirmation checks all bookings and occupancy again. Times use '.$h($zone).'.</p>';
        if(!($s['canReserve']??true))$x.='<p>New reservations are restricted by the current demonstration plan. Existing bookings are retained for safe completion.</p>';elseif($tables)$x.=self::form($s,$csrf,'reserve',['timezone_version'=>$s['settings']['version']]).self::select('Table','table',$tables).self::input('Synthetic guest name','guest').self::input('Party size','party','2','number').self::input('Local arrival time · '.$zone,'start',Seating::local($s['now']+600,$zone,'Y-m-d\TH:i'),'datetime-local').self::input('Expected duration in minutes','minutes','60','number').self::input('Internal notes (optional)','notes','','text',false).'<button>Create request</button></form>';
        else $x.='<p>Add a table before making reservations.</p>';
        $x.='</section><section class="panel" id="reservations"><h2>Reservations</h2><p>Up to 500 records, pending first. Check-in opens 15 minutes before arrival. Completing a seated booking releases its table.</p><div class="seating-filters"><label>Search guest or reference<input type="search" data-reservation-search></label><label>Status<select data-reservation-status><option value="">All statuses</option>';foreach(['REQUESTED','CONFIRMED','SEATED','COMPLETED','CANCELLED','NO_SHOW']as $status)$x.='<option>'.$status.'</option>';
        $today=Seating::local($s['now'],$zone,'Y-m-d');$x.='</select></label><label>When<select data-reservation-period><option value="">All loaded records</option><option value="today">Today</option><option value="upcoming">Upcoming</option></select></label></div><p data-reservation-count role="status"></p><div class="seating-bookings">';
        foreach($s['reservations']as $r){$id=$r['reservation_id'];$x.='<article class="seating-booking" id="reservation-'.$h($id).'" data-reservation="'.$h($id).'" data-status="'.$r['status'].'" data-today="'.(Seating::local((int)$r['start_epoch'],$zone,'Y-m-d')===$today?'1':'0').'" data-upcoming="'.((int)$r['start_epoch']>=$s['now']?'1':'0').'"><div class="seating-booking-title"><h3>'.$h($r['guest_name']).'</h3><span class="seating-badge">'.$h(str_replace('_',' ',$r['status'])).'</span></div><p><strong>'.$h($tables[$r['table_id']]??'Retained table').'</strong> · Party '.$r['party_size'].'</p><p>'.$when($r['start_epoch']).' → '.$when($r['end_epoch']).' '.$h($zone).'</p><p>Reference '.$h($r['reference_code']).($r['checked_in_epoch']?' · Checked in '.$when($r['checked_in_epoch']):'').'</p><p>'.$h($r['notes']).'</p><div class="seating-actions">';
            $base=['reservation'=>$id,'version'=>$r['version']];$next=match($r['status']){'REQUESTED'=>['CONFIRMED'=>'Confirm','CANCELLED'=>'Cancel request'],'CONFIRMED'=>['SEATED'=>'Seat guest','CANCELLED'=>'Cancel reservation','NO_SHOW'=>'Mark no-show'],'SEATED'=>['COMPLETED'=>'Complete & release table'],default=>[]};
            if(($s['canReserve']??true)&&$r['status']==='CONFIRMED'&&$r['checked_in_epoch']===null)$x.=self::form($s,$csrf,'checkin',$base).'<button>Check in guest</button></form>';
            foreach($next as $status=>$label){if(!($s['canReserve']??true)&&in_array($status,['CONFIRMED','SEATED'],true))continue;if($status==='SEATED'&&$r['checked_in_epoch']===null)continue;$x.=self::form($s,$csrf,'transition',$base+['status'=>$status]).'<button'.(in_array($status,['CANCELLED','NO_SHOW'],true)?' class="seating-secondary"':'').'>'.$label.'</button></form>';}
            $x.='</div>';if($next&&($s['canReserve']??true))$x.='<details><summary>Change assigned table</summary>'.self::form($s,$csrf,'assign',$base).self::select('New table','table',$tables,$r['table_id']).self::input('Reassignment reason','reason').'<button>Reassign table</button></form></details>';$x.='</article>';
        }
        $x.='</div>'.(!$s['reservations']?'<p>No reservations yet. Create a synthetic request to begin.</p>':'').'</section>';
        if($s['canConfigure']){
            $x.='<section class="panel" id="configuration"><h2>Floor & table configuration</h2><p>Owners and outlet managers configure seating. Assigned cashiers manage daily reservations.</p><details><summary>Restaurant timezone</summary>'.self::form($s,$csrf,'timezone',['version'=>$s['settings']['version']]).'<label>IANA timezone<input name="timezone" value="'.$h($zone).'" required list="seating-timezones"></label><datalist id="seating-timezones">';foreach(['UTC','Asia/Kolkata','Asia/Dhaka','Europe/London','America/New_York']as $tz)$x.='<option value="'.$tz.'">';$x.='</datalist><p>Changing timezone changes display only. Existing booking instants remain unchanged.</p><button>Save timezone</button></form></details>';
            foreach([null,...$s['floors']]as $f){$x.='<details><summary>'.($f?'Edit floor · '.$h($f['name']):'Add floor').'</summary>'.self::form($s,$csrf,'floor',['id'=>$f['floor_id']??'','version'=>$f['version']??'0']).self::input('Floor name','name',$f['name']??'').self::select('Floor activation','active',['1'=>'Active','0'=>'Inactive'],(string)($f['active']??1)).'<button>Save floor</button></form></details>';}
            if($floors)foreach([null,...$s['tables']]as $t)$x.='<details><summary>'.($t?'Edit table · '.$h($t['name']):'Add table').'</summary>'.self::form($s,$csrf,'table',['id'=>$t['table_id']??'','version'=>$t['version']??'0']).self::select('Floor','floor',$floors,$t['floor_id']??'').self::input('Table name','name',$t['name']??'').self::input('Seating capacity','capacity',(string)($t['capacity']??4),'number').self::select('Table type','type',['standard'=>'Standard','booth'=>'Booth','bar'=>'Bar','outdoor'=>'Outdoor','private'=>'Private'],$t['table_type']??'standard').self::select('Table activation','active',['1'=>'Active','0'=>'Inactive'],(string)($t['active']??1)).self::input('Table notes (optional)','notes',$t['notes']??'','text',false).'<button>Save table</button></form></details>';
            $x.='</section>';
        }
        $x.='<section class="panel" id="seating-history"><h2>Seating activity</h2><p>Latest 200 immutable events · '.$h($zone).'. Historical reservations are retained.</p>';foreach($s['events']as $event)$x.='<details><summary>'.$h(ucfirst($event['operation'])).' · '.$when($event['occurred_epoch']).' · '.$h($event['display_name']).'</summary><p>Request '.$h($event['request_id']).'</p></details>';return $x.'</section></main></body></html>';
    }
}
